<?php require __DIR__.'/app/bootstrap.php'; $u=require_user(); $msg='';$err='';
function ticket_upload(int $messageId): void { if(empty($_FILES['attachment']['name'])||($_FILES['attachment']['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return; if($_FILES['attachment']['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Attachment upload failed.'); if($_FILES['attachment']['size']>10*1024*1024)throw new RuntimeException('Attachment is larger than 10 MB.'); $name=basename((string)$_FILES['attachment']['name']);$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));$allowed=['png','jpg','jpeg','gif','webp','pdf','txt','log','zip'];if(!in_array($ext,$allowed,true))throw new RuntimeException('Attachment type is not allowed.');$dir=__DIR__.'/storage/tickets';if(!is_dir($dir)&&!mkdir($dir,0750,true))throw new RuntimeException('Could not create ticket storage.');$stored=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($_FILES['attachment']['tmp_name'],$dir.'/'.$stored))throw new RuntimeException('Could not save attachment.');$mime=(string)(mime_content_type($dir.'/'.$stored)?:'application/octet-stream');$q=db()->prepare('INSERT INTO support_attachments(message_id,original_name,stored_name,mime_type,file_size) VALUES(?,?,?,?,?)');$q->execute([$messageId,$name,$stored,$mime,(int)$_FILES['attachment']['size']]); }
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$a=$_POST['action']??'';if($a==='new'){$subject=trim($_POST['subject']??'');$body=trim($_POST['message']??'');if($subject===''||$body==='')throw new RuntimeException('Subject and message are required.');$cat=in_array($_POST['category']??'', ['technical','billing','sales','abuse','other'],true)?$_POST['category']:'technical';$pri=in_array($_POST['priority']??'', ['low','normal','high','urgent'],true)?$_POST['priority']:'normal';$sid=(int)($_POST['service_id']??0)?:null;db()->prepare("INSERT INTO support_tickets(user_id,service_id,subject,category,priority,status) VALUES(?,?,?,?,?,'awaiting_staff')")->execute([$u['id'],$sid,$subject,$cat,$pri]);$tid=(int)db()->lastInsertId();db()->prepare('INSERT INTO support_messages(ticket_id,user_id,message) VALUES(?,?,?)')->execute([$tid,$u['id'],$body]);ticket_upload((int)db()->lastInsertId());header('Location: /support.php?id='.$tid);exit;}if($a==='reply'){$tid=(int)$_POST['ticket_id'];$q=db()->prepare('SELECT * FROM support_tickets WHERE id=? AND user_id=?');$q->execute([$tid,$u['id']]);if(!$q->fetch())throw new RuntimeException('Ticket not found.');$body=trim($_POST['message']??'');if($body==='')throw new RuntimeException('Reply cannot be empty.');db()->prepare('INSERT INTO support_messages(ticket_id,user_id,message) VALUES(?,?,?)')->execute([$tid,$u['id'],$body]);ticket_upload((int)db()->lastInsertId());db()->prepare("UPDATE support_tickets SET status='awaiting_staff',updated_at=NOW() WHERE id=?")->execute([$tid]);header('Location: /support.php?id='.$tid);exit;}if($a==='close'){db()->prepare("UPDATE support_tickets SET status='closed' WHERE id=? AND user_id=?")->execute([(int)$_POST['ticket_id'],$u['id']]);$msg='Ticket closed.';}}catch(Throwable $e){$err=$e->getMessage();}}
$services=db()->prepare("SELECT id,name FROM services WHERE user_id=? AND status<>'terminated' ORDER BY id DESC");$services->execute([$u['id']]);$services=$services->fetchAll();$id=(int)($_GET['id']??0);$ticket=null;$messages=[];if($id){$q=db()->prepare('SELECT t.*,a.name assigned_name FROM support_tickets t LEFT JOIN users a ON a.id=t.assigned_admin_id WHERE t.id=? AND t.user_id=?');$q->execute([$id,$u['id']]);$ticket=$q->fetch();if($ticket){$q=db()->prepare('SELECT m.*,u.name, u.role FROM support_messages m LEFT JOIN users u ON u.id=m.user_id WHERE m.ticket_id=? AND m.is_internal=0 ORDER BY m.id');$q->execute([$id]);$messages=$q->fetchAll();}}$q=db()->prepare('SELECT * FROM support_tickets WHERE user_id=? ORDER BY updated_at DESC');$q->execute([$u['id']]);$tickets=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FoxNetwork | Support</title><link rel="stylesheet" href="/assets/portal.css?v=7.0"></head><body><div class="app"><aside class="side"><div class="brand"><img src="/images/logo.png"><span>FOX<b>NETWORK</b></span></div><nav class="nav"><a href="/">Overview</a><a href="/store.php">Store</a><a href="/orders.php">Orders</a><a class="active" href="/support.php">Support</a></nav><nav class="nav bottom"><a href="/settings.php">Account Settings</a><a href="/logout.php">Sign out</a></nav></aside><main class="main"><header><div class="profile"><div><b><?=e($u['name'])?></b><div class="muted" style="font-size:12px">Customer</div></div><div class="avatar"><?=e(strtoupper(substr($u['name'],0,1)))?></div></div></header><div class="content"><div class="eyebrow">FOXNETWORK SUPPORT CENTER</div><h1>How can we help?</h1><p class="muted">Open a ticket or continue an existing conversation with our team.</p><?php if($msg):?><div class="notice"><?=e($msg)?></div><?php endif?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif?>
<div class="support-grid"><section class="card"><div class="cardhead"><b>NEW TICKET</b></div><form method="post" enctype="multipart/form-data" class="ticket-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="new"><label>Subject<input name="subject" maxlength="190" required placeholder="What do you need help with?"></label><div class="admin-form-grid"><label>Category<select name="category"><option value="technical">Technical</option><option value="billing">Billing</option><option value="sales">Sales</option><option value="abuse">Abuse</option><option value="other">Other</option></select></label><label>Priority<select name="priority"><option>normal</option><option>low</option><option>high</option><option>urgent</option></select></label><label>Related service<select name="service_id"><option value="">None</option><?php foreach($services as $s):?><option value="<?=e($s['id'])?>"><?=e($s['name'])?></option><?php endforeach?></select></label></div><label>Message<textarea name="message" rows="6" required></textarea></label><label>Attachment <span class="muted">optional, max 10 MB</span><input type="file" name="attachment" accept=".png,.jpg,.jpeg,.gif,.webp,.pdf,.txt,.log,.zip"></label><button class="btn primary">Create ticket</button></form></section><section class="card"><div class="cardhead"><b>MY TICKETS</b><span class="muted"><?=count($tickets)?></span></div><div class="ticket-list"><?php if(!$tickets):?><div class="empty muted">No support tickets yet.</div><?php endif?><?php foreach($tickets as $t):?><a class="ticket-row <?=$id===$t['id']?'selected':''?>" href="/support.php?id=<?=$t['id']?>"><div><b>#<?=$t['id']?> <?=e($t['subject'])?></b><small><?=e(ucfirst($t['category']))?> · <?=e(ucfirst($t['priority']))?></small></div><span class="admin-badge status-<?=e($t['status'])?>"><?=e(strtoupper(str_replace('_',' ',$t['status'])))?></span></a><?php endforeach?></div></section></div>
<?php if($ticket):?><section class="card ticket-thread"><div class="cardhead"><div><b>#<?=e($ticket['id'])?> <?=e($ticket['subject'])?></b><div class="muted small"><?=e(ucfirst($ticket['category']))?> · <?=e(ucfirst($ticket['priority']))?><?=!empty($ticket['assigned_name'])?' · Assigned to '.e($ticket['assigned_name']):''?></div></div><span class="admin-badge status-<?=e($ticket['status'])?>"><?=e(strtoupper(str_replace('_',' ',$ticket['status'])))?></span></div><div class="messages"><?php foreach($messages as $m):?><article class="message <?=$m['is_staff']?'staff':'customer'?>"><div class="message-meta"><b><?=e($m['name']?:($m['is_staff']?'FoxNetwork Staff':'Customer'))?></b><span><?=e($m['created_at'])?></span></div><div><?=nl2br(e($m['message']))?></div></article><?php endforeach?></div><?php if($ticket['status']!=='closed'):?><form method="post" enctype="multipart/form-data" class="ticket-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="reply"><input type="hidden" name="ticket_id" value="<?=$ticket['id']?>"><textarea name="message" rows="4" required placeholder="Write a reply..."></textarea><input type="file" name="attachment" accept=".png,.jpg,.jpeg,.gif,.webp,.pdf,.txt,.log,.zip"><button class="btn primary">Send reply</button></form><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="close"><input type="hidden" name="ticket_id" value="<?=$ticket['id']?>"><button class="btn">Close ticket</button></form><?php endif?></section><?php endif?></div></main></div></body></html>
